mod solution;

fn main() {
    let cases = [
    (r#"[6, 4, 9, 7] target=13"#, r#"1,2"#),
    (r#"[2, 8] target=10"#, r#"0,1"#),
    (r#"
[2, 8] target=10
"#, r#"0,1"#),
    (r#"  
[6, 4, 9, 7] target=13
  "#, r#"1,2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS complement-lookup");
}
